    {
      "question": "Statement 1: Asset K generated higher annual yield than Asset L.\nStatement 2: Asset L generated higher annual yield than Asset M.\nStatement 3: Asset M generated higher annual yield than Asset K.\n\nIf the first two statements are true, the third statement is:",
      "options": [
        {
          "id": "A",
          "text": "True"
        },
        {
          "id": "B",
          "text": "Cannot be determined"
        },
        {
          "id": "C",
          "text": "Definitively False"
        },
        {
          "id": "D",
          "text": "Partially True"
        },
        {
          "id": "E",
          "text": "Uncertain"
        }
      ],
      "correctOption": "C",
      "explanation": "**Correct Answer: C** (Definitively False)\n\nBy transitivity, Yield(K) > Yield(L) and Yield(L) > Yield(M) means Yield(K) > Yield(M). Therefore, Asset M > Asset K is definitively False.\n\n\ud83d\udca1 **Speed Tip:** Rapidly isolate target clues and eliminate mismatched categories in <8s.",
      "category": "verbal",
      "subType": "syllogism"
    }
